// Filter rows ready to be dialed, with strict phone validation.
// Skips rows with missing/invalid/unreachable phones so we never hit VAPI 400s
// or waste calls on truncated/typo'd numbers.

const now = new Date();
const retryEligibleStatuses = ['No Answer', 'Voicemail', 'Busy'];
const MAX_RETRIES = 5;

// --------- Phone validation ---------
// Returns { valid: bool, reason: string, normalized: string }
// Strategy:
//   1. Must start with '+' (E.164)
//   2. If +1 (US/Canada): strict NANP rules
//        - Exactly 11 digits total
//        - Area code (NPA): 3 digits, first digit 2-9, can't be N11 codes (e.g., 211, 311, 411, 511, 611, 711, 811, 911)
//        - Exchange code (NXX): 3 digits, first digit 2-9
//   3. Other countries: 8-15 digits total (general E.164 spec), warn-only
const validatePhone = (raw) => {
  if (!raw) return { valid: false, reason: 'empty' };
  const s = String(raw).trim();
  if (!s.startsWith('+')) return { valid: false, reason: 'missing_plus_prefix' };

  const digits = s.replace(/\D/g, '');
  if (digits.length < 8) return { valid: false, reason: `too_short_${digits.length}_digits` };
  if (digits.length > 15) return { valid: false, reason: `too_long_${digits.length}_digits` };

  // NANP-specific validation (+1)
  if (digits.startsWith('1')) {
    if (digits.length !== 11) {
      return { valid: false, reason: `nanp_must_be_11_digits_got_${digits.length}` };
    }
    const npa = digits.substring(1, 4);   // area code
    const nxx = digits.substring(4, 7);   // exchange
    // Area code first digit must be 2-9
    if (!/^[2-9]/.test(npa)) {
      return { valid: false, reason: `invalid_area_code_starts_with_${npa[0]}` };
    }
    // N11 codes (211, 311, etc.) are reserved
    if (/^[2-9]11$/.test(npa)) {
      return { valid: false, reason: `reserved_n11_area_code_${npa}` };
    }
    // Exchange first digit must be 2-9
    if (!/^[2-9]/.test(nxx)) {
      return { valid: false, reason: `invalid_exchange_starts_with_${nxx[0]}` };
    }
    // Middle digit 9 in exchange = service code, skip
    // (optional, some legit numbers use it â€” leaving loose for now)
  }

  return { valid: true, reason: 'ok', normalized: '+' + digits };
};

const ready = [];
const skipped = [];

for (const item of $input.all()) {
  const row = item.json;
  const status = String(row.call_status ?? '').trim();
  const retryCount = parseInt(row.retry_count ?? 0, 10) || 0;
  const nextRetryStr = String(row.next_retry_at ?? '').trim();
  const nextRetry = nextRetryStr ? new Date(nextRetryStr) : null;
  const phone = String(row.phone ?? '').trim();

  // Status gate
  let statusReady = false;
  if (status === 'Pending') {
    statusReady = true;
  } else if (retryEligibleStatuses.includes(status) && retryCount < MAX_RETRIES) {
    if (!nextRetry || now >= nextRetry) statusReady = true;
  }

  if (!statusReady) continue;

  // Phone validation gate
  const check = validatePhone(phone);
  if (!check.valid) {
    skipped.push({
      row_number: row.row_number,
      name: `${row.first_name || ''} ${row.last_name || ''}`.trim(),
      phone: phone,
      reason: check.reason
    });
    continue;
  }

  // Valid â€” push with normalized phone
  ready.push({
    json: {
      ...row,
      phone: check.normalized,
      __row_number: row.row_number ?? null
    }
  });
}

// Visible in execution logs
if (skipped.length > 0) {
  console.log('âš  Skipped rows with invalid phones:', JSON.stringify(skipped, null, 2));
}
console.log(`Ready: ${ready.length} | Skipped: ${skipped.length}`);

return ready;

// Build the VAPI outbound call payload for ONE lead row.
// Uses the Sergio Tapia (Outbound Broker) assistant.
// Builds a personalized firstMessage from whatever fields are populated,
// and passes full lead context via variableValues so the system prompt
// can naturally reference known data.

const row = $input.item.json;

// ---- Helpers ----
const trim = (v) => String(v || '').trim();
const hasVal = (v) => v !== null && v !== undefined && String(v).trim() !== '' && String(v).toLowerCase() !== 'unknown';

// ---- Pull raw fields ----
const firstName = trim(row.first_name);
const lastName = trim(row.last_name);
const phone = trim(row.phone);
const email = trim(row.email);
const state = trim(row.state);
const propertyType = trim(row.property_type);
const loanType = trim(row.loan_type);
const transactionType = trim(row.transaction_type);
const loanAmountRaw = trim(row.loan_amount_requested);
const inquirySource = trim(row.inquiry_source);
const inquiryDate = trim(row.inquiry_date);

// FICO: prefer explicit f&f number, fallback to DSCR range
const ficoRaw = trim(row.ff_credit_score) || trim(row.dscr_credit_score_range);

// ---- Formatters for voice naturalness ----
// Spoken dollar: 310000 â†’ "three hundred ten thousand dollars"
// We pass numeric to the prompt and let the system prompt's pronunciation
// rules handle it â€” but firstMessage needs spelled-out, so format here.
const spellMoney = (raw) => {
  if (!raw) return '';
  const n = Number(String(raw).replace(/[^0-9.]/g, ''));
  if (!n || isNaN(n)) return String(raw);
  if (n >= 1000000) {
    const m = (n / 1000000).toFixed(1).replace(/\.0$/, '');
    return `${m} million dollars`;
  }
  if (n >= 1000) {
    const k = Math.round(n / 1000);
    // turn into words roughly â€” 310 â†’ "three hundred ten thousand"
    const words = numToWords(k);
    return `${words} thousand dollars`;
  }
  return `${numToWords(n)} dollars`;
};

// Very small number-to-words for 0..999 (enough for our use)
function numToWords(n) {
  const ones = ['zero','one','two','three','four','five','six','seven','eight','nine','ten','eleven','twelve','thirteen','fourteen','fifteen','sixteen','seventeen','eighteen','nineteen'];
  const tens = ['','','twenty','thirty','forty','fifty','sixty','seventy','eighty','ninety'];
  n = Math.round(n);
  if (n < 20) return ones[n];
  if (n < 100) {
    const t = Math.floor(n / 10), o = n % 10;
    return tens[t] + (o ? '-' + ones[o] : '');
  }
  if (n < 1000) {
    const h = Math.floor(n / 100), rest = n % 100;
    return ones[h] + ' hundred' + (rest ? ' ' + numToWords(rest) : '');
  }
  return String(n);
}

const transactionNatural = transactionType ? transactionType.toLowerCase() : '';
const loanAmountSpoken = hasVal(loanAmountRaw) ? spellMoney(loanAmountRaw) : '';

// ---- Build personalized firstMessage ----
// We construct the opening carefully based on what we know. Sergio's
// system prompt tells him not to re-ask for these, so the first turn
// establishes what WE know and invites them into the conversation.

let opener = `Hi ${firstName || 'there'}, Sergio Tapia here.`;

// Add inquiry reference if we have enough context
const contextParts = [];
if (hasVal(loanAmountSpoken) && hasVal(propertyType)) {
  contextParts.push(`I'm looking at your inquiry regarding ${loanAmountSpoken} for your ${propertyType.toLowerCase()}`);
} else if (hasVal(loanAmountSpoken)) {
  contextParts.push(`I'm looking at your inquiry regarding ${loanAmountSpoken}`);
} else if (hasVal(propertyType)) {
  contextParts.push(`I'm looking at your inquiry on your ${propertyType.toLowerCase()}`);
} else {
  contextParts.push(`I'm looking at your recent inquiry`);
}
if (hasVal(state)) {
  contextParts[contextParts.length - 1] += ` in ${state}`;
}

let details = '';
if (hasVal(transactionNatural)) {
  details = ` and you're looking to ${transactionNatural.toLowerCase()}`;
}

opener += ` ${contextParts.join(' ')}${details}. Do you have a quick minute?`;

// ---- Build variableValues for system-prompt templates ----
const variableValues = {
  first_name: firstName || 'there',
  last_name: lastName || '',
  phone: phone || '',
  email: email || '',
  state: hasVal(state) ? state : 'unknown',
  property_type: hasVal(propertyType) ? propertyType : 'unknown',
  known_loan_type: hasVal(loanType) ? loanType : 'unknown',
  transaction_type: hasVal(transactionType) ? transactionType : 'unknown',
  loan_amount_requested: hasVal(loanAmountRaw) ? loanAmountSpoken : 'unknown',
  fico: hasVal(ficoRaw) ? String(ficoRaw) : 'unknown',
  inquiry_source: hasVal(inquirySource) ? inquirySource : 'your online inquiry',
  inquiry_date: hasVal(inquiryDate) ? inquiryDate : 'unknown'
};


// ---- Retell outbound call payload ----
// NOTE: Set from_number to your Retell phone number once porting completes.
const payload = {
  agent_id: 'agent_8c36983cac060850dfb961406d',  // Sergio Tapia (Outbound Broker)
  from_number: '<RETELL_PHONE_NUMBER>',           // Replace after phone porting
  to_number: phone,
  retell_llm_dynamic_variables: {
    dynamic_opening: opener,
    first_name: variableValues.first_name,
    last_name: variableValues.last_name,
    phone: variableValues.phone,
    email: variableValues.email,
    state: variableValues.state,
    property_type: variableValues.property_type,
    known_loan_type: variableValues.known_loan_type,
    transaction_type: variableValues.transaction_type,
    loan_amount_requested: variableValues.loan_amount_requested,
    fico: variableValues.fico,
    inquiry_source: variableValues.inquiry_source,
    inquiry_date: variableValues.inquiry_date
  },
  metadata: {
    source: 'outbound_dialer',
    persona: 'sergio_tapia',
    sheet_row_number: String(row.row_number ?? ''),
    phone: phone
  }
};

return { json: { payload, row } };
